26: 	constructor({
27: 		generator,
28: 		name,
29: 		value,
30: 		parent
31: 	}: {
32: 		generator: DomGenerator,
33: 		name: string,
34: 		value: Node[],
35: 		parent: Element
36: 	}) {
37: 		this.type = 'Attribute';
38: 		this.generator = generator;
39: 		this.parent = parent;
40: 
41: 		this.name = name;
42: 		this.value = value;
43: 	}
